\begin{aligned}\lim_{t\to0^{+}}\frac{1}{t^{6}}\int_{0}^{t}\mathrm{d}x\int_{x}^{t}\sin(x y)^{2}\mathrm{d}y&\xlongequal{ 交换积分次序 }\lim_{t\to0^{+}}\frac{1}{t^{6}}\int_{0}^{t}\mathrm{d}y\int_{0}^{y}\sin(x y)^{2}\mathrm{d}x\\&\xlongequal{ 洛必达法则 }\lim_{t\to0^{+}}\frac{\int_{0}^{t}\sin(x t)^{2}\mathrm{d}x}{6t^{5}}\\&\xlongequal{x t=u}\frac{1}{6}\lim_{t\to0^{+}}\frac{\int_{0}^{t^{2}}\sin u^{2}\mathrm{d}u}{t^{6}}=\frac{1}{6}\lim_{t\to0^{+}}\frac{\int_{0}^{t^{2}}u^{2}\mathrm{d}u}{t^{6}}\\&=\frac{1}{6}\lim_{t\to0^{+}}\frac{\frac{t^{6}}{3}}{t^{6}}=\frac{1}{18}.\end{aligned}
$$

